<answer>\begin{align*}\lfloor S^2\rfloor&=\left\lfloor\left(\sum_{n=1}^{2007}\dfrac{n}{n+1}+\sum_{n=1}^{2007}\dfrac1{n}\right)^2\right\rfloor\\&=\left\lfloor\left(\sum_{n=1}^{2007}\dfrac{n+1-1}{n+1}+\sum_{n=1}^{2007}\dfrac1{n}\right)^2\right\rfloor\\&=\left\lfloor\left(\sum_{n=1}^{2007}1-\sum_{n=1}^{2007}\dfrac1{n+1}+\sum_{n=1}^{2007}\dfrac1{n}\right)^2\right\rfloor\\&=\left\lfloor\left(2007-\dfrac1{2008}+1\right)^2\right\rfloor\\&=\boxed{4031030}.\end{align*}
</answer>

